CREATE TABLE public.contact_messages (id uuid primary key default gen_random_uuid(), name text not null, email text not null, reason text not null, message text not null, created_at timestamptz not null default now()); GRANT INSERT ON public.contact_messages TO anon, authenticated; GRANT SELECT ON public.contact_messages TO authenticated; GRANT ALL ON public.contact_messages TO service_role; ALTER TABLE public.contact_messages ENABLE ROW LEVEL SECURITY; CREATE POLICY "Visitors submit contact messages" ON public.contact_messages FOR INSERT TO anon, authenticated WITH CHECK (length(name) between 1 and 80 and length(email) between 3 and 254 and length(message) between 10 and 5000 and length(reason) between 1 and 100); CREATE POLICY "Admins read contact messages" ON public.contact_messages FOR SELECT TO authenticated USING (public.journal_has_role(auth.uid(), ARRAY['admin','super_admin'])); CREATE OR REPLACE FUNCTION public.enforce_journal_post_workflow() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RETURN NEW; END IF; IF TG_OP='UPDATE' THEN IF NOT public.journal_has_role(auth.uid(),ARRAY['editor','senior_editor','publisher','admin','super_admin']) AND (OLD.created_by_user_id IS DISTINCT FROM auth.uid() OR OLD.status NOT IN ('draft','in_review')) THEN RAISE EXCEPTION 'Insufficient editorial permission'; END IF; IF OLD.created_by_user_id IS DISTINCT FROM NEW.created_by_user_id THEN RAISE EXCEPTION 'Post ownership cannot be reassigned'; END IF; END IF; IF NEW.status IN ('published','scheduled') AND (TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status) AND NOT public.journal_has_role(auth.uid(),ARRAY['publisher','admin','super_admin']) THEN RAISE EXCEPTION 'Only publishers can publish or schedule'; END IF; IF NEW.status='approved' AND (TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status) AND NOT public.journal_has_role(auth.uid(),ARRAY['senior_editor','publisher','admin','super_admin']) THEN RAISE EXCEPTION 'Only senior editors can approve'; END IF; IF NEW.status='scheduled' AND (NEW.scheduled_for IS NULL OR NEW.scheduled_for<=now()) THEN RAISE EXCEPTION 'A future schedule is required'; END IF; NEW.updated_at=now(); RETURN NEW; END; $$; CREATE TRIGGER enforce_journal_post_workflow BEFORE INSERT OR UPDATE ON public.posts FOR EACH ROW EXECUTE FUNCTION public.enforce_journal_post_workflow(); CREATE POLICY "Publishers update posts" ON public.posts FOR UPDATE TO authenticated USING (public.journal_has_role(auth.uid(),ARRAY['publisher'])) WITH CHECK (public.journal_has_role(auth.uid(),ARRAY['publisher'])); CREATE OR REPLACE FUNCTION public.audit_journal_post_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_log(actor_id,action,entity_type,entity_id,diff) VALUES(auth.uid(),CASE WHEN TG_OP='INSERT' THEN 'post.create' ELSE 'post.update' END,'post',NEW.id,jsonb_build_object('status',NEW.status,'slug',NEW.slug)); RETURN NEW; END; $$; CREATE TRIGGER audit_journal_post_change AFTER INSERT OR UPDATE ON public.posts FOR EACH ROW EXECUTE FUNCTION public.audit_journal_post_change(); CREATE OR REPLACE FUNCTION public.journal_subscription_preferences(_categories text[], _unsubscribe boolean default false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE account_email text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; account_email=auth.jwt()->>'email'; IF array_length(_categories,1)>12 THEN RAISE EXCEPTION 'Too many categories'; END IF; UPDATE public.newsletter_subscribers SET category_preferences=_categories,status=CASE WHEN _unsubscribe THEN 'unsubscribed' ELSE status END,updated_at=now() WHERE lower(email)=lower(account_email); END; $$; REVOKE ALL ON FUNCTION public.journal_subscription_preferences(text[],boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.journal_subscription_preferences(text[],boolean) TO authenticated; CREATE POLICY "Subscribers read own preferences" ON public.newsletter_subscribers FOR SELECT TO authenticated USING (lower(email)=lower(auth.jwt()->>'email')); REVOKE SELECT ON public.newsletter_subscribers FROM authenticated; GRANT SELECT(id,email,name,status,created_at,confirmed_at,category_preferences) ON public.newsletter_subscribers TO authenticated;